-- Substitui modelos públicos legados por versões empresariais Freemarker.
-- Requer V119 e pode ser executada novamente com segurança.
START TRANSACTION;

-- Ofício
SET @id_mod = (SELECT ID_MOD FROM ex_modelo WHERE HIS_ATIVO=1 AND NM_MOD='Ofício' ORDER BY ID_MOD DESC LIMIT 1);
SET @id_arq = (SELECT m.ID_ARQ FROM ex_modelo m JOIN corporativo.cp_arquivo a ON a.ID_ARQ=m.ID_ARQ WHERE m.ID_MOD=@id_mod AND m.NM_DIRETORIO='ENFAS' AND a.HASH_SHA256='ad469d0d14b7fe7d2864523fee882979289c7e094d1bab894474b3b56505cc1b' LIMIT 1);
